// Arithmetic-range renormalization of a VP6 encoder bitstream.
struct Rva009AC390State
{
	unsigned int m_code;
	unsigned int m_range;
	int m_unused08;
	int m_bitCount;
	int m_outputCount;
	unsigned char *m_output;
};

void rva009AC390RangeEncode(Rva009AC390State *state, int ignored, unsigned int probability)
{
	unsigned int code = state->m_code;
	unsigned int range = state->m_range;
	int count = state->m_bitCount;
	unsigned int split = (((range - 1) * probability) >> 8) + 1;
	range -= split;
	code += split;
	while (range < 128)
	{
		range <<= 1;
		if ((int)code < 0)
		{
			int index = state->m_outputCount - 1;
			while (index >= 0 && state->m_output[index] == 255)
			{
				state->m_output[index] = 0;
				--index;
			}
			++state->m_output[index];
		}
		code <<= 1;
		if (++count == 0)
		{
			state->m_output[state->m_outputCount] = (unsigned char)(code >> 24);
			++state->m_outputCount;
			count = -8;
			code &= 0xffffff;
		}
	}
	state->m_range = range;
	state->m_code = code;
	state->m_bitCount = count;
}
